  imagePool: ["/main_ch3_02A.png"],
  background: "/bg_dark_room.png",
  text: `‘그럼 입장 테스트부터 해볼까요.’

메시지를 보내자 근떡존의 답장이 바로 왔다.

‘테스트요?’

‘네.’

‘전진협 입장 자격 심사.’

근떡존은 잠시 조용했다.

그리고 답했다.

‘저 지금 좀 긴장되는데요.’

잠깐 뒤.

‘아니 많이요.’

또 잠깐 뒤.

‘면접보다 더 긴장됩니다.’

그 말이 웃겨서 전진협에 그대로 옮겼다.

‘히든: 근떡존 전진협 면접본대 ㅋ’

방은 바로 폭발했다.

‘근바섭: ㅇㅁㅇㅁ.....’

‘아로벤: 첫 번째 질문. 근육 보여줄 수 있나요?’

‘쮋: 두 번째 질문. 상탈 가능하신가요?’

‘금수: 아....이런...’

‘흩밤: 엘레강스~함을 시~험해보져?’

근떡존에게 첫 번째 질문을 보냈다.

‘첫 번째 문제.’

‘전진협에는 컨셉 게이짓을 하는 사람들이 있습니다. 원래 게임 내 길드톡방 이었는데 그 길드가 게이컨셉길드 였거든요.’

‘감당 가능?’

근떡존은 한참 답하지 않았다.

입력 중 표시가 떴다가 사라졌다.
또 떴다가 사라졌다.

아마 그는 지금 엄청난 속도로 생각하고 있을 것이다.

이걸 농담으로 받아야 하나.
진지하게 답하면 너무 티 나나.
그렇다고 너무 거리두면 이상한 사람처럼 보이나.

한참 뒤 답장이 왔다.

‘게이짓의 범위가 어디까지인가요.’

그 문장을 보고 웃음이 터졌다.

전진협에 그대로 옮기자 반응이 쏟아졌다.

‘쮋: 가능성 있다’

‘아로벤: 이새끼 된다’

‘근바섭: ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ헐 옵 귀여워...’

‘타조: 딩가딩가딩 보여주죠?’

근떡존은 또 메시지를 보냈다.

‘아니 그냥.’

‘제가 이상하게 답하면 분위기 망칠까 봐요.’

잠깐 뒤.

‘농담이면 받아칠 수 있는데.’

또 잠깐 뒤.

‘진짜면 제가 좀 긴장할 것 같아서요.’

진짜면.

그 단어가 묘하게 눈에 걸렸다.

‘두 번째 문제.’

‘저는 방에서 이런 말을 주로 합니다.’

히든은 잠깐 망설이다가, 전진협에서 자주 했던 말을 조금 순화해 보냈다.

‘아 어디 나만 바라봐줄 근육떡대존잘남 없나...’

‘나만 바라보고 나만 집착해줄 남자 없냐고 진짜.’

‘난 왜 옆에 남자가 없지.’

보내고 나서, 이상하게 화면을 바로 볼 수가 없었다.

근떡존에게 이걸 보여주는 건 묘하게 민망했다.

그동안 근떡존 앞에서 보여줬던 자신은 차분하고 여유 있는 쪽이었다.
그런데 저 문장들은 완전히 달랐다.

외롭고, 히스테릭하고, 남자를 원하고, 누군가가 자신만 바라봐주길 바라는 사람.

근떡존은 읽고도 한동안 답하지 않았다.

침묵이 길었다.

너무 길었다.

괜히 보냈나 싶을 때쯤, 답장이 왔다.

‘히든님.’

짧은 한마디.

곧이어 다음 메시지.

‘이거 진짜예요?’

손이 멈췄다.

어떻게 답해야 할지 몰랐다.

‘농담 반 진심 반?’

그렇게 보내자 근떡존의 읽음 표시가 바로 떴다.

하지만 다시 답은 늦었다.

한참 뒤, 메시지가 왔다.

‘이거.’

잠깐 뒤.

‘제가 그 조건에 좀 맞는 것 같은데요.’

심장이 잠깐 이상하게 뛰었다.

근떡존은 바로 추가 메시지를 보냈다.

‘아니 죄송합니다.’

‘너무 급발진했죠.’

‘농담입니다.’

잠깐 뒤.

‘반쯤.’

또 잠깐 뒤.

‘아니 이걸 어떻게 수습하지.’

전진협에 이 흐름을 조금만 옮기자 방은 난리가 났다.

‘근바섭: ㅁㅊ 이새끼 대놓고 형한테 플러팅ㅇ짓 하는데요?’

‘아로벤: 와 씨발 바로 각재네’

‘타조: 야. 축하한다. 또 한명 주웠네.’

근떡존은 그걸 몰랐다.

그는 아직 개인 카톡창에서 혼자 당황하고 있었다.

‘히든님.’

‘저 방금 말 이상했죠.’

‘근데.’

‘진짜 조금은 그렇게 생각했어요.’

잠깐 뒤.

‘제가 히든님만 바라볼 수는 있을 것 같아서요.’`,
