  imagePool: ["/main_ch3_02B.png"],
  background: "/bg_room_night.png",
  text: `‘뭘 들키는 게 무서워요?’

보내자 근떡존은 바로 읽었다.

하지만 답은 오지 않았다.

이번 침묵은 평소의 허둥대는 침묵과 달랐다.

조금 더 깊었다.

한참 뒤 메시지가 왔다.

‘음.’

잠깐 뒤.

‘제가 생각보다 이상한 사람인 거요.’

그 문장만 보면 평소의 자기비하처럼 보였다.

하지만 이번엔 뭔가 달랐다.

‘어떤 식으로요?’

근떡존은 다시 조용해졌다.

입력 중 표시가 몇 번이나 떴다가 사라졌다.

그리고 마침내 답장이 왔다.

‘저 겉으로 보면 그냥 평범하잖아요. 맞나..?’

‘그냥..덩치 크고.’

‘그런데 사실은 그렇게 단순하지만은 않아서요.’

잠깐 뒤.

‘좋아하는 사람 앞에서는 생각도 많아지고.’

‘겁도 많아지고.’

‘상대가 조금만 멀어지는 것 같으면 혼자 불안해지고.’

또 잠깐 뒤.

‘그리고.’

그 다음 메시지는 꽤 오래 오지 않았다.

근떡존은 아마 거기서 한참 멈춰 있었을 것이다.

그리고.

그 뒤에 붙을 말이 무엇인지,
히든도 어렴풋이 예상했다.

몇 분 뒤, 메시지가 왔다.

‘남자를 좋아하는 것도요.’

화면을 바라봤다.

근떡존은 이어서 보냈다.

‘아.’

‘이거 너무 갑자기였죠.’

‘죄송해요.’

‘근데 히든님이 물어보셔서.’

‘아니 그래도 너무 갑자기긴 한데.’

‘하.’

그가 얼마나 당황했는지 문장만 봐도 알 수 있었다.

근떡존은 계속 메시지를 보냈다.

‘처음 만났을 때부터 말하면 안 된다고 생각했어요.’

‘제가 히든님 좋다고 티 내면.’

‘히든님이 불쾌해할 수도 있잖아요.’

‘남자가 남자한테 그러는 거 싫어하는 사람도 많고.’

‘그리고 제가 이렇게 생겨서.’

‘괜히 더 부담스러울까 봐요.’

그 문장을 읽고, 편의점 앞의 근떡존이 떠올랐다.

쿠폰 하나에도 쩔쩔매던 큰 남자.
조심스럽게 웃고,
농담으로 자기 진심을 덮던 사람.

그 안에 이런 마음을 숨기고 있었던 것이다.

처음부터.

‘저 처음에 히든님 보고 좀 좋았어요.’

잠깐 뒤.

‘좀이 아닌가.’

또 잠깐 뒤.

‘사실 많이요.’

이번에는 장난이 없었다.

근떡존은 스스로 도망갈 곳을 줄이고 있었다.

‘근데 무서웠어요.’

‘히든님이 질색하면.’

‘그건 좀 많이 아플 것 같아서요.’

전진협 창을 열자, 마침 방에서는 이런 말들이 올라오고 있었다.

‘근바섭: 또 한명의 히든 피해자가...’

‘아로벤: 또 버림당하겠네ㅋ;;;’

‘유칼립투스나무: 하매화 시키죠’

평소라면 웃겼을 텐데,
이번에는 조금 조용히 보게 됐다.

근떡존의 고백은 방의 드립보다 훨씬 조심스러웠다.

그는 장난처럼 다가오고 싶었지만,
장난으로만 남고 싶지는 않은 사람 같았다.`,
