  imagePool: ["/main_ch3_04C.png"],
  background: "/bg_room_night.png",
  text: `‘농담이에요, 진심이에요?’

메시지를 보내자, 근떡존은 한동안 조용했다.

이번엔 쉽게 도망갈 수 없는 질문이었다.

그는 평소처럼 농담으로 빠져나갈 수도 있었다.

‘하하 농담입니다.’
‘제가 또 이상한 소리를 했네요.’
‘운동 끝나서 도파민 때문입니다.’

그런 식으로.

하지만 이번에는 그러지 않았다.

한참 뒤 답장이 왔다.

‘둘 다요.’

잠깐 뒤.

‘농담으로 말해야 덜 무섭고.’

또 잠깐 뒤.

‘진심으로 말하면 히든님이 도망갈까 봐요.’

그 문장을 읽고, 마음이 조금 묵직해졌다.

근떡존은 이어서 보냈다.

‘저 사실 이런 말 잘 못해요.’

‘남자 좋아한다고 하는 것도.’

‘누구한테 관심 있다고 하는 것도.’

‘처음부터 티내면 이상하게 볼까 봐.’

또 잠깐 뒤.

‘특히 저는 겉모습이 좀 그렇잖아요.’

‘덩치도 크고.’

‘운동도 하고.’

‘그런 사람이 갑자기 남자한테 이러면.’

‘부담스러울 수도 있으니까.’

근떡존은 자기 자신을 아주 조심스럽게 설명하고 있었다.

그 조심스러움이 오히려 그의 오래된 두려움을 보여줬다.

그는 강해 보이는 외형 때문에,
자기 마음이 더 위협적으로 보일까 봐 겁냈다.

사실은 섬세하고,
상처받기 쉽고,
거절당할까 봐 먼저 웃는 사람인데.

‘그래서.’

‘게이짓도.’

‘일단은 농담처럼 해볼게요.’

잠깐 뒤.

‘히든님 잘생겼잖아요 ㅋㅋ 제 취향입니다.’

또 잠깐 뒤.

‘그리고 꼴...’

또 잠깐 뒤.

‘아 여기까지 하겠습니다 하하.’

그 메시지를 보고 웃음이 터졌다.

근떡존이 얼마나 필사적으로 선을 밟았다가 도망치는지 너무 잘 보였다.

전진협에 그대로 옮기자 방은 뒤집혔다.

‘근바섭: 와씨 뭐야 개 걸레년이었잖아 그냥????’

‘쮋: 노련한데효? 한두명한테 저런게 아닌거같은데. 좀 싸한ㅋ’

‘아로벤: 씨발섹스해너네제발히든레이프갱뱅강간해기존전남친다모아서감금제발’

‘타조: 근데 저분 겨드랑이는 시큼하신거 맞나영?’

‘금수: 나는 순형이가 너무 좋아’

근떡존은 아직 방 반응을 몰랐다.

개인 카톡에서 또 메시지가 왔다.

‘저 방금 진짜 이상했죠.’

‘근데.’

‘히든님이 싫어하지 않으면.’

‘조금씩 더 해볼게요.’

그는 천천히,
정말 천천히 다가오고 있었다.

하지만 방향은 분명했다.`,
