  imagePool: ["/pure_ch10_04.png"],
  background: "/bg_street_evening.png",
  text: `해가 천천히 기울었다.

근떡존이 이마를 떼고 똑바로 섰다. 이마에 살짝 자국이 남아 있었다. 그가 그것을 한 번 만지작거리더니 작게 웃었다.

"흔적 남았어요."

"그러게."

"좋네요."

"흔적이?"

"네."

근떡존이 그 말을 하고는 한 박자 멈췄다. 그리고 평소보다 조금 큰 목소리로 덧붙였다.

"근데, 이렇게 가까이 있어도 돼요?"

"이미 어깨에 부빈 사람이 할 말은 아닌데."

"...맞네요. 헤헤."

또 헤헤가 나왔다. 본인은 그 단어가 자기 입에서 나온 줄도 모르는 것 같았다.

둘은 다시 걷기 시작했다. 이번엔 손을 잡고 걸었다. 어제보다 자연스러운 손이었다. 깍지를 끼는 데 망설임이 없었다.

골목 끝 작은 가게 앞을 지나갈 때였다.

가게 안에서 누군가 누군가를 부르는 소리가 들렸다.

"형! 잠깐만!"

평범한 말이었다. 가게 직원이 동생인 듯한 사람을 부르는 소리. 그 두 사람이 어떤 관계인지는 모르지만, 형, 이라는 단어가 평범하게 공기 안에 떠올랐다 사라졌다.

근떡존이 그 단어를 듣고 잠깐 멈췄다.

"왜?"

근떡존이 시선을 옆으로 돌리고 있었다.

귀가 빨개져 있었다.

"떡존아."

"...네."

"왜 그래."

"아니요."

"아닌 게 아닌데."

근떡존이 잠깐 망설이다, 작게 입을 열었다.

"방금."

"응."

"저도."

"응."

"형, 이라고 한 번 불러보고 싶었는데."

"..."

"용기가 안 났어요."

골목의 끝에서 가로등이 한 등 켜졌다.

"불러봐."

"...진짜요?"

"진짜."

근떡존이 한 번 침을 삼켰다. 그리고 시선을 발끝으로 떨궜다. 그리고 다시 들었다. 그리고 또 떨궜다.

그러다 결국 입을 열었다.

"형."

아주 작은 목소리였다.

너무 작아서 거의 입김 같았다.

"한 번 더."

"..."

"한 번 더 불러봐."

"형."

이번엔 좀 더 컸다. 그래도 평소 그가 ~선생님 부를 때 목소리에 비하면 절반쯤이었다. 자기 입에서 그 한 글자가 나오는 게 본인도 적응이 안 되는 모양이었다.

"이상해요."

"왜."

"입에 안 익어요."

"적응되겠지."

"네."

근떡존이 천천히 웃었다.

"근데."

"응."

"형, 좋네요."

좋네요, 라는 말이 나오면서 그의 얼굴이 한 번 더 환해졌다. 가로등 빛 아래에서 그 얼굴이 거의 어린 사람처럼 보였다.

"형."

"응."

"또 불러볼래요."

"마음대로."

"형. 형."

"...너무 자주 부르는 거 아냐."

"적응 중이에요."

"적응 중."

"네. 형."

근떡존이 깍지 낀 손에 살짝 힘을 줬다. 잡혀 있다는 것을 한 번 더 확인하는 손짓이었다.

이름이 바뀌었다. 호칭이 바뀌었다. 거리가 바뀌었다.

그러나 가장 크게 바뀐 건 그의 얼굴 자체였다.

전엔 늘 살짝 굳어 있었던 표정이, 오늘은 종일 풀려 있었다. 이렇게 살갑게, 이렇게 단순하게, 이렇게 강아지처럼 좋아할 수 있는 사람이었다는 걸 그 자신도 처음 알게 된 것 같았다.

그게 사랑이라는 것을, 본인보다 먼저 옆에서 보고 있었다.

순애 루트 10장 종료.

다음 챕터 예고: 11장 — 형의 일상.`,
