  background: "/bg_park_evening.png",
  text: `해 질 무렵의 작은 공원 벤치였다.

근떡존이 먼저 와 앉아 있었다. 발끝을 보고 있었다. 다가가는 발소리를 듣고도 한 번 더 발끝을 보다가, 천천히 고개를 들었다.

"형."

이번엔 카톡이 아니라 입으로 나온 호칭이었다. 입으로 나온 형, 은 카톡으로 본 형보다 훨씬 더 뜨끔한 무게가 있었다.

"왔다."

"네."

"앉아."

"앉을게요."

옆자리가 비어 있었다. 자연스럽게 그 자리에 앉았다.

근떡존은 잠깐 침묵을 두었다. 그리고 입을 열었다.

"형."

"응."

"저 오늘 자제하려고 했어요."

"뭘?"

"전진협도 안 보려고 하고, 메시지도 먼저 안 보내려고 하고."

잠깐 뒤.

"그런데 두 시간 만에 다 무너졌어요."

근떡존이 작게 웃었다. 자조에 가까운 웃음이었다.

"두 시간이면 잘 버틴 거 아냐?"

"전진협 47개 안 읽고는 못 살겠더라고요."

"47개?"

"네. 점심쯤 됐는데 47개 쌓여 있었어요."

"47개 쌓일 정도로 시끄러웠나, 우리 방."

"네. 평소대로요."

"평소대로면 별일 없었겠네."

"맞아요."

"근데 못 참았어?"

"네."

근떡존이 손을 내려다봤다. 손가락을 한 번 깍지 끼었다 풀었다. 그 동작이 어제까지의 그라면 변명이 따라붙을 자리였는데, 오늘은 변명이 없었다.

"형."

"응."

"저 안 되겠어요."

"뭐가."

"자제가요."

"왜."

근떡존이 잠깐 시선을 들었다. 어두워지기 시작한 하늘 아래에서, 그의 눈은 평소보다 조금 안정되어 보였다.

"형이 다 안다고 했잖아요."

"응."

"그 말 듣고 나서, 더 자제가 안 돼요."

"왜?"

"안 들킨 척하느라 쓰던 에너지가, 다 풀려버려서요."

선생님은 잠깐 그 말을 곱씹었다.

근떡존이 말한 게 맞았다.

그동안 그는 자기 안의 것을 들키지 않으려고 매일 무언가를 누르며 살아왔다. 답장 빨리 보고 싶은 마음. 위치 확인하고 싶은 마음. 다른 사람의 이름을 보면 신경 쓰이는 마음. 그 모든 걸 누르는 데에는 적지 않은 에너지가 들었을 것이다.

그런데 어제 선생님이 알아요, 라고 한마디 한 순간, 그 에너지가 풀려버렸다.

들켰으니까. 더 이상 숨길 필요가 없으니까.

그래서 더 못 참는 사람이 되어버렸다.

이 또한, 알아준다는 것의 함정이었다.

"형."

"응."

"저 어떡해요."

"뭘 어떡해."

"이렇게 자제 못하는 사람이 돼버렸어요."

"원래도 자제 잘 하던 사람은 아니었잖아."

"...그건 그래요."

근떡존이 작게 웃었다.

"근데 이전엔 적어도 노력은 했거든요."

"이젠 노력도 안 해?"

"노력하는 척이라도 하려면, 들키지 말아야 하는데."

"이미 다 들킨 상태라."

"네."

"노력이 의미가 없어졌어요."

이상한 논리였다. 그러나 근떡존 안에서는 분명한 논리였다.

들키지 않은 사람만이 노력할 수 있다. 들킨 사람은 그저 자기를 받아주는 사람 옆에서 솔직해질 수밖에 없다.

선생님은 그 논리가 어디로 흘러갈지 어렴풋이 알 것 같았다.

"형."

"응."

"저 이제, 형 옆에서 자제 안 할래요."

"뭐를."

"형 보고 싶을 때 보고 싶다고 말하고. 답장 늦으면 늦으냐고 묻고. 다른 사람이랑 있으면 신경 쓰인다고 하고."

잠깐 뒤.

"그래도 돼요?"

선생님은 잠시 그를 봤다.

이건 부탁처럼 보였지만, 동시에 통보이기도 했다. 자제하지 않겠다는 통보. 들킨 사람의 권리 같은 것을 주장하는 통보.

위험한 통보였다. 그러나 어떤 면에서는 정직한 통보이기도 했다.`,
