  background: "/bg_room_day.png",
  text: `45분이 지났다.

방광 85%.

이 수치에서, 근떡존은 인생 처음으로 알게 됐다.

자기가 평소에 안다고 생각했던 "오줌 마려움"이 사실 아무것도 아니었다는 것을.

85%는 차원이 달랐다.

아랫배의 압박감이 더 이상 둔한 감각이 아니었다. 살아있는 압력이었다. 그것은 안에서 바깥으로, 매 순간, 끊임없이 출구를 찾고 있었다. 한 방향으로 미는 힘이었다. 떡존이의 의지와는 무관하게, 자기 살길을 찾고 있었다.

근떡존은 두 손으로 허벅지를 꽉 쥐었다.

다리는 이미 바짝 붙여 X자로 꼬여 있었다.

발끝이 살짝 안쪽으로 모였다.

평소 그라면 절대 잡지 않을 자세였다. 그러나 지금은 이 자세가 유일한 방어선이었다.

"...으."

작은 신음이 새어 나왔다.

본인도 자기가 그 소리를 냈다는 게 믿기지 않았다.

그러나 신음을 한 번 내고 나니, 조금 나았다.

소리를 낸다는 건 — 어딘가로 에너지를 분산시키는 일이었다. 안쪽으로 모이는 압박이, 입 밖으로 나가면서 살짝 줄었다.

근떡존은 그것을 알게 됐다.

"으...읍."

다시 한번.

"으...윽..."

잠깐 침묵.

"...씨발."

처음으로 욕이 나왔다.

평소 떡존이라면 절대 안 했을 욕이었다. 그러나 85%의 방광 앞에서는 사회적 가면이 천천히 무너지기 시작했다. 그가 평소 보여주던 정중함, 차분함, 단정함. 그 모든 것이 한 점 — 자기 사타구니 부근 — 으로 수렴되며 흐려졌다.

이제 그는 그저 한 마리의, 화장실 가고 싶은, 큰 덩치의 인간이었다.

선생님은 회의 중이었다.

회의 소리가 평소보다 가까이 들렸다. 떡존의 청각이 예민해졌기 때문이었다. 모든 감각이 비정상적으로 또렷해지고 있었다. 시계의 초침 소리가 들렸다. 옆방 냉장고의 모터 소리가 들렸다. 멀리 누군가의 자전거 벨 소리도 들렸다.

전부 다 — 물 소리처럼 들렸다.

그게 가장 잔혹한 부분이었다.

세상 모든 소리가 물 소리로 들리기 시작했다.

"...선생님."

근떡존이 작게 불렀다.

목소리가 조금 떨렸다.

"...선생님."

선생님은 회의에 집중하고 있었다. 듣지 못했다. 들어도 지금은 답할 수 없었다.

방광 87%.

근떡존은 자기 사타구니 부근을 두 손으로 꽉 눌렀다. 그러면 안에 있는 것이 못 나올 거라는, 어렴풋한 본능이었다. 의학적으로 맞는 동작인지는 모른다. 그러나 그 순간 그가 할 수 있는 모든 것이었다.

방광 88%.

"...으아아."

작은 비명이 새어 나왔다.

이제는 그저 신음이 아니었다. 비명에 가까웠다.

자기 사타구니를 두 손으로 누르고, 다리를 X자로 꼰 채로, 작은 비명을 내며 떨고 있는 큰 덩치의 금발 남자.

평소 그가 봤다면 뭐 이런 새끼가 있냐고 했을 그림이었다.

그러나 지금은 그 그림이 자기 자신이었다.

방광 90%.`,
