  text: `방광 100%.

여기서, 인간은 — 의학적으로 — 위험해진다.

방광이 100% 차오르면, 보통 사람은 그 직전에 무조건 비웠다. 자기 의지로 비우지 않더라도, 자기도 모르게 흘리게 되거나, 무의식 중에 일어나서 화장실로 가거나, 어떻게든 — 비웠다.

그러나 근떡존은 비우지 않았다.

그는 좋아하는 사람의 일에 폐를 끼치지 않으려고 했다. 그 마음이 너무 강해서, 그의 몸이 비우는 것 자체를 거부하고 있었다.

이건 의지력의 영역이 아니었다.

이건 사랑의 영역이었다.

방광 100.0%. 100.1%. 100.2%.

평범한 사람의 방광은 100%에서 터졌어야 했다.

그러나 떡존의 방광은 — 그 큰 덩치만큼 — 평균보다 컸다.

한반도의 평균 1.7배. (단군이 다녀간 그 한반도다.)

그래서 그의 방광은 100%를 넘어, 105%까지 — 늘어나면서 — 버티고 있었다.

근떡존의 시야가 흐려졌다.

처음에는 그저 눈에 힘이 빠지는 줄 알았다. 그런데 아니었다.

시야 끝부터 색이 변하고 있었다.

붉은색.

주황색.

노란색.

녹색.

파란색.

남색.

보라색.

방 안의 풍경이 천천히 무지개로 물들었다.

"...?"

근떡존은 자기 눈을 의심했다. 너무 참아서 시신경이 망가진 줄 알았다. 그렇게 생각하는 것이 그가 할 수 있는 가장 합리적인 추론이었다.

그러나 다음 순간, 천장에서 한 줄기 빛이 내려왔다.

황금빛이었다.

영적인 빛이었다.

근떡존이 어렸을 때 교회에서 본 스테인드글라스처럼, 어딘가 신성한 분위기를 풍기는 빛이었다.

선생님이 그를 안고 비틀거리고 있는 작은 거실 안으로, 그 빛이 천천히 내려왔다.

『...떡존아!!? 너 갑자기 왜 빛나!!?』

선생님의 목소리가 멀리서 들렸다.

근떡존은 자기 몸이 황금빛에 감싸이는 것을 느꼈다.

그 빛이 그를 비추는 순간, 그는 자기 안에서 무언가가 풀려나는 것을 느꼈다.

방광 100.5%.

그러나 터지지 않았다.

대신, 그의 의식이 어디론가 빨려 들어가기 시작했다.

위로.

아니면 안으로.

아니면 어딘가 — 인간의 좌표계로는 설명할 수 없는 곳으로.

선생님이 그를 부둥켜안고 있었다.

"...떡존아!!"

마지막으로 그가 들은 것은, 어디선가 들려오는 작은 목소리였다.

『...오랫동안 기다려왔다, 그대를.』

근떡존의 의식이 흐려졌다.

5장 종료.

다음 챕터 예고: 6장 — 방광 요정과 요도니아.`,
