  kind: "normal",
  min: { affinity: 9999 },
  imagePool: ["/bladder_ch7_02.png"],
  background: "/bg_convenience.png",
  text: `결국 둘은 편의점으로 갔다.

근떡존이 시연을 하겠다고 했다. 백 마디 말보다 한 번 보는 게 낫다고.

선생님은 처음엔 어이없어했다. 그러나 떡존이 너무 진지했고, 진지하게 도와달라고 부탁했고, 진지하게 코카콜라 페트병 1.5L 6개를 사겠다고 카운터에 들고 갔다.

선생님이 옆에서 결제를 도왔다.

"진짜 다 마실 거야?"

"네."

"6개를?"

"네."

"...."

"걱정하지 마세요. 안 죽습니다."

근떡존은 카페로 돌아가지 않고, 편의점 바로 옆 작은 공원의 벤치에 앉았다. 거기가 시연 장소였다.

페트병 6개를 가지런히 줄 세웠다.

빨간 콜라 6병이 햇볕에 반짝였다.

지나가던 행인들이 흘끔흘끔 봤다. 큰 덩치의 금발 남자가 1.5L 콜라 6개를 늘어놓고 진지한 얼굴로 앉아 있는 광경은, 평범한 오후 풍경은 아니었다.

"시작합니다."

근떡존이 첫 번째 페트병을 들었다.

뚜껑을 땄다. 치익, 하는 소리. 거품이 살짝 올라왔다.

그가 입에 댔다.

원샷.

1.5L. 9초.

근떡존이 페트병을 내려놓았다. 트림조차 하지 않았다.

선생님은 입을 살짝 벌리고 그를 봤다.

"...."

"두 번째 갑니다."

두 번째 페트병. 1.5L. 11초.

세 번째. 1.5L. 12초.

네 번째 즈음부터 떡존의 배가 살짝 부풀기 시작했다. 그러나 그것은 일반인의 배가 부르는 양상이 아니었다. 그저 살짝 풍선이 부푸는 정도였다. 표정에는 변화가 없었다.

다섯 번째. 1.5L. 14초.

여섯 번째. 1.5L. 16초.

총 9L의 콜라를 마신 사람이 벤치에 앉아서, 평온한 얼굴로 멀리 하늘을 바라보고 있었다.

근떡존은 트림 한 번을 하고 나서, 옆을 돌아봤다.

"보셨어요?"

선생님은 대답하지 않았다.

선생님은, 그저, 가만히 떡존을 보고 있었다.

표정이 묘했다. 떡존이 본 적 없는 종류의 표정이었다.

평소 선생님의 다정함과도 달랐다. 평소의 장난스러움과도 달랐다. 평소의 단단함과도 달랐다.

그것은 — 어떤 인간이 살면서 처음으로 자기보다 위대한 것을 마주했을 때 짓는 표정에 가까웠다.

종교적인 표정이었다.

『근떡존...』

선생님이 작게 입을 열었다.

목소리가 평소와 살짝 달랐다.

『방광이...』

『...너무 듬직하다...』

근떡존이 잠시 멈칫했다.

방광이 듬직하다.

그게 무슨 뜻인지 잘 모르겠지만, 일단 칭찬으로 받아들이기로 했다.

"감사합니다."

선생님은 그 감사 인사를 듣고도 떡존에게서 시선을 떼지 못했다. 정확히는, 떡존의 배 부근에서 시선을 떼지 못했다.

선생님은 작게 자기 자신에게 중얼거렸다.

『이게... 매력인가...?』

근떡존은 그 말을 들었다.

들었지만, 아무 말도 못 했다.

그가 9L의 콜라를 다 마신 것보다 더 충격적인 일이, 방금 옆에서 일어난 것 같았다.



【새 스탯 등장 — 방광매력】

『선생님 안에서 무언가가 영구적으로 변경되었습니다.』

방광 루트 7장 첫 부분 종료.`,
