  imagePool: ["/pure_ch11_02.png"],
  background: "/bg_cafe_evening.png",
  text: `7시 정각, 카페 문이 열렸다.

근떡존이 들어오는 모습은 평소와 달랐다.

평소엔 문을 한 번 열고, 두리번거리고, 발견하면 천천히 다가오는 사람이었다. 오늘은 문을 열기도 전에 이미 안쪽을 향해 있었다. 문이 열림과 동시에 그가 바로 시선을 맞추고, 그 자리에서 한 번 환하게 웃었다.

웃음이 평소와 달랐다.

평소엔 미소가 한 번 누른 뒤에 천천히 올라오는 사람이었다. 오늘은 미소가 통제 없이, 그저 입꼬리 끝부터 올라가더니, 결국 양쪽 뺨이 다 부풀 정도로 활짝 웃어버렸다.

거의 강아지 같은 웃음이었다.

"형!"

성큼성큼 다가왔다.

"안 늦었네."

"네!"

"기특하다."

"...."

근떡존이 잠깐 멈춰 섰다.

"왜."

"기특하다는 말이 좋아서요."

"그래?"

"네."

"한 번만 더 해주세요."

"기특하다."

근떡존이 자리에 앉으면서 작게 헤헤, 하고 웃었다.

평소엔 헤헤가 우연히 새어 나오던 단어였다. 그런데 오늘은 그 단어가 더 자주, 더 자연스럽게 나왔다. 마치 그가 헤헤라는 음을 발음하는 데 처음으로 부끄러움을 잃은 사람처럼.

커피가 나왔다. 근떡존은 자기 컵을 들지 않고, 먼저 형의 컵 가까이 손을 내밀었다. 손가락이 컵을 만지는 게 아니라, 컵 옆의 빈자리를 만지듯 살짝 머물렀다. 그것은 손을 잡고 싶다는 신호였다. 잡아달라는 신호.

손을 잡아주자 그가 곧장 깍지를 끼었다.

"형."

"응."

"오늘 좀 길게 있어요."

"길게?"

"네."

"얼마나."

"...밤까지요."

그가 말하면서 시선을 떨궜다. 그러나 떨군 시선의 끝이 다시 슬쩍 올라와 형을 향했다. 그것은 부끄러움인 동시에 기다림이었다. 거절당하면 어쩌지 하는 작은 두려움과, 거절당하지 않을 거라는 작은 확신이 동시에 깃든 시선이었다.

"이유 있어?"

"있어요."

"뭔데."

"형이 안 보이면 좀 그래서요."

좀 그래서요, 라고 그가 말했지만 그 짧은 한 마디 안에는 훨씬 더 많은 결이 담겨 있었다. 좀 그렇다는 말이 무엇을 의미하는지, 그가 지금까지 어떤 마음으로 형 없는 시간을 견뎌왔는지, 그리고 그 시간이 그에게 점점 더 어려워지고 있다는 것까지 — 한 줄에 다 담겨 있었다.

이 사람이 분리불안이라는 단어를 알고 있다면, 자기 안의 그것을 알아챘을지도 몰랐다.

그러나 그는 모르는 채로 그저 어리광을 부리고 있었다. 그 어리광이 너무 정직해서 오히려 위험하지 않았다. 숨김이 없었기 때문에, 안에 가둬두지 않았기 때문에, 그것은 그저 다정함의 형태로 흘러나오고 있을 뿐이었다.

"길게 있어도 돼."

"진짜요?"

"진짜."

근떡존의 얼굴이 또 한 번 환해졌다. 이번엔 입꼬리뿐만이 아니었다. 눈매가 천천히 휘어지고, 광대가 살짝 올라오고, 평소엔 단단해 보이던 콧날조차 어딘가 부드러워진 듯했다.

행복할 때 사람의 얼굴은 이렇게 다른 사람이 되는구나, 처음으로 알게 됐다.

"형."

"응."

"저 오늘 하루 종일 형 생각만 했어요."

"거짓말."

"진짜로요."

"학교에서도?"

"네."

"운동할 때도?"

"네."

"밥 먹을 때도?"

"네 헤헤."

마지막 헤헤가 너무 자연스러워서, 더 이상 부끄러워하지 않는다는 게 분명했다.

그가 그동안 안에 잠가두었던 것들이 — 어리광이든, 응석이든, 그저 좋아한다고 말하고 싶은 마음이든 — 이제는 별다른 노력 없이 그저 흘러나오고 있었다.

이게 — 좋아한다는 것의 가장 다정한 모양이라는 것을, 옆에서 보고 있는 사람이 천천히 알아가고 있었다.`,
