  background: "/bg_park_night.png",
  text: `해가 완전히 졌다.

카페에서 나와 작은 공원을 걸었다. 가을의 끝자락이었다. 바람이 차가워졌고, 길에는 잎이 거의 다 떨어진 나무들이 줄지어 서 있었다. 가로등 아래로 걷는 발걸음 소리만 가끔 들렸다.

근떡존은 형의 손을 잡고 걸으면서, 평소보다 말이 적었다.

행복할 때 그는 말이 많아지는 사람이었다. 그런데 오늘은 너무 행복해서 오히려 말이 줄어든 것 같았다. 마음 안쪽이 가득 차서, 굳이 말로 흘려보내지 않아도 되는 종류의 행복이었다.

그러나 잠깐 걷다가 그가 갑자기 멈췄다.

"형."

"응."

"잠깐만요."

"왜."

근떡존이 시선을 발끝으로 떨궜다. 잠깐 침묵이 흘렀다. 그러다 그가 천천히 입을 열었다.

"형 한 번만 안아도 돼요."

부탁이었다. 평소의 그라면 안고 싶을 때 그저 안았을 것이다. 그러나 오늘은 묻고 있었다. 안고 싶다는 마음이 너무 커서 — 묻지 않으면 그 마음 자체가 흩어져버릴 것 같다는 듯이.

그를 향해 한 발 다가갔다.

근떡존이 천천히 두 팔을 벌리고, 키 차이가 나는 형을 자기 쪽으로 끌어당겼다.

큰 몸이 작은 몸을 감쌌다.

평소엔 조심스럽기만 하던 그가, 오늘은 한 번 안고 나서 놓지 않았다.

처음엔 잠깐 안고 떨어질 줄 알았다. 그런데 그가 점점 더 깊이 안았다. 두 팔의 힘이 천천히 더 들어갔다. 그러다 어느 순간, 그의 어깨가 작게 떨리기 시작했다.

"...떡존아?"

"...네."

"왜 그래."

"...."

대답이 없었다.

"왜 그러는지 말해봐."

"...."

침묵이 길었다. 그러다 그의 목 안쪽에서 작은 소리 하나가 새어 나왔다.

흐읍, 하는 소리였다.

울음을 참는 소리.

근떡존이 울고 있었다.

그를 안은 채로, 가만히, 큰 몸이 작게 떨리며, 그가 울고 있었다.

"...떡존아."

"...."

"왜 울어."

"...죄송합니다."

"왜 죄송해."

"우는 거 보이려고 한 거 아닌데..."

목소리가 평소보다 한 톤 낮았다. 떨리고 있었다. 큰 덩치의 사람이 그 떨림을 숨기지 못해서, 그 자체가 너무 솔직하게 보이고 있었다.

"...왜 우는데."

"모르겠어요."

"....."

"진짜 모르겠어요."

근떡존이 천천히 안은 팔을 풀었다. 그가 시선을 떨군 채로 자기 손등으로 눈가를 한 번 닦았다. 그 동작이 너무 어색했다. 본인이 자기 눈물을 닦는 일에 익숙하지 않은 사람의 동작이었다.

"...형이 너무 좋아서요."

천천히 그가 말했다.

"형이 너무 좋은 게... 너무 무서워서요."

"무서워?"

"네."

"왜."

"형이 어느 날 갑자기... 사라질 것 같아서요."

"...."

"제가 이렇게 좋아하는데, 형이 어느 날 그냥 없어지면."

"제가 어떻게 살지 모르겠어서요."

근떡존이 다시 한번 눈가를 닦았다. 그러나 닦을수록 더 흘러나왔다. 평소엔 그가 닦으면 멈췄을 종류의 것이, 오늘은 멈추지 않고 자기 길을 따라 흘러내리고 있었다.

"....."

"형."

"응."

"저 평소엔 안 울거든요."

"...그래."

"근데 왜 오늘은 이렇게 갑자기 풀리는지 모르겠어요."

"....."

"....."

"형이 너무 좋으니까."

"좋으면 우는 거야?"

"네."

"그런 거였어?"

"네."

"....."

근떡존이 다시 한번 형을 안았다. 이번엔 천천히. 그리고 이번에는 안은 채로 작은 목소리로 말했다.

"형 한 번만 약속해주세요."

"뭘."

"안 사라진다고요."

"...."

"제가 너무 좋아하니까. 안 사라진다고 해주세요."

이건 어리광이 아니었다.

이건 그가 평생 잠가두었던 두려움 하나가, 오늘 처음으로 형 앞에서 풀려나오는 순간이었다.

그동안 그가 보여주지 않던 눈물 안에는, 그가 한 번도 누구에게도 말하지 않았던 외로움이 같이 들어 있었다.

잠가두지 않으면 살아갈 수 없었던 종류의 외로움.

그리고 잠가두는 동안에는 자기조차 만질 수 없었던 외로움.

그것이 오늘, 형이라는 한 사람의 품 안에서, 천천히 풀려나오고 있었다.`,
