  imagePool: ["/obsession_ch11_01.png"],
  background: "/bg_dark_room.png",
  text: `매일.

이 두 글자가 처음 입에서 나왔을 때, 그것은 약속이었다.

10장의 그 골목, 형이 매일 만나도 어렵겠지만 노력해보겠다고 했던 그 한 마디. 그게 떡존의 안에서 그날 밤 내내 메아리쳤다.

매일. 매일. 매일.

자고 일어나서도 그 단어가 머릿속에 있었다. 양치를 하면서도, 옷을 입으면서도, 아침 메시지를 보내면서도, 그 단어 하나가 그의 모든 행동의 배경음으로 깔려 있었다.

매일.

처음 며칠은 정말로 매일 만났다.

월요일에 카페에서. 화요일에 저녁을. 수요일에는 영화 한 편. 목요일에 또 카페. 금요일엔 형 집 근처 산책.

근떡존은 그 매일이 너무 행복했다. 너무 행복해서, 행복이 자기 몸 어디까지 차오를 수 있는지 시험하는 것 같았다.

그러나 행복이라는 것은 — 한 번 임계점을 넘으면 다른 무언가로 변하는 종류의 감정이었다.

토요일.

형이 처음으로 약속을 잡지 못했다.

'떡존아 형 오늘 학교 일이 너무 많아서 좀 어려울 것 같아'

그 메시지가 도착한 순간, 떡존의 안쪽 어딘가에서 무언가가 무너졌다.

평소라면 이해할 수 있는 메시지였다. 일이 많은 사람이 일이 많은 날 약속을 잡지 못하는 건 당연한 일이었다.

그러나 평소가 평소가 아니었다.

그는 매일이라는 단어를 약속처럼 받아들이고 있었다. 매일 만난다는 게 아니라, 매일 — 형이 자기를 보고 있다는 — 그런 종류의 매일이었다.

그게 — 토요일에 무너졌다.

근떡존은 휴대폰을 손에 들고 한참 동안 침대에 앉아 있었다.

침대 옆 벽시계가 째깍거렸다. 평소엔 들리지도 않던 그 소리가 오늘은 너무 크게 들렸다. 째깍. 째깍. 째깍. 그 소리에 맞춰서 그의 가슴 안쪽 어딘가가 한 번씩 조여왔다.

답장을 보냈다.

'네 형 일 잘 보세요'

읽음 표시가 떴다. 그러나 답장은 없었다.

평소라면 형은 답장을 잘 해주는 사람이었다.

오늘은 안 했다.

이유는 간단했을 것이다. 일이 많아서. 그저 그뿐이었다.

그러나 떡존의 안에서는 그 간단한 사실이 전혀 간단하지 않게 작동했다.

그 5분 동안 그가 떠올린 것들은 — 정상적인 사람이라면 떠올리지 않을 종류의 것들이었다.

형이 일이 많은 게 아니라 자기를 피하는 거라는 가능성. 어제 자기가 한 어떤 말이 형을 짜증나게 했다는 가능성. 어제 카페에서 자기가 너무 어리광을 부려서 형이 부담스러워한다는 가능성. 형이 다른 사람을 만나기 시작했다는 가능성. 그 다른 사람과 지금 같이 있다는 가능성.

가능성들이 가지를 치고, 또 가지를 치고, 또 가지를 쳤다.

5분이 50분처럼 길었다.

근떡존은 자기 머리를 한 번 손으로 짚었다.

"...씨발."

작은 목소리가 새어 나왔다.

자기가 이상하다는 걸 알았다. 5분 동안 답장 안 온 것 가지고 이렇게까지 머릿속이 폭주하는 게 — 분명히 정상이 아니라는 걸 그도 알았다.

그러나 알면서 멈출 수 있는 종류의 것이었다면, 애초에 시작도 안 했을 것이다.

그는 머리를 두 손으로 한 번 부여잡았다.

머릿속이 — 그의 머릿속이 — 자기 통제권 밖으로 가고 있었다.

방광이 통제권 밖으로 가던 5장 어느 시점처럼.

그러나 이번엔 방광이 아니라 — 마음이었다.`,
