  background: "/bg_room_evening.png",
  text: `여지를 받은 그 한 박자.

평소의 떡존이라면 그 박자를 또 한 번 흘려보냈을 것이다. 망설였을 것이다. 죄송하다고 했을 것이다. 너무 부담스러우셨죠 라고 변명했을 것이다.

그러나 오늘의 그는 — 그 박자를 흘려보내지 않았다.

여지가 열린 그 한 순간에, 그가 — 망설임 없이 — 형의 얼굴 쪽으로 몸을 기울였다.

너무 빨라서 형도 살짝 놀란 정도였다.

평소의 떡존답지 않게 — 결정적인 순간에 망설임을 한 톨도 두지 않은 행동이었다. 평소엔 다섯 번 망설이던 사람이, 오늘은 단 한 번도 망설이지 않았다.

문이 열렸다는 신호를 받자마자 — 그는 그 문을 통과했다.

입술이 닿았다.

근떡존이 평생 처음으로 하는 키스였다.

처음 1초는 — 자기가 무엇을 하고 있는지 인식이 안 됐다. 평생 자기와 무관한 단어였던 그 행위를, 자기가 지금 하고 있다는 것이 — 머리가 따라가지 못했다.

그러다 2초.

3초.

4초.

천천히 — 머리가 따라잡았다.

자기가 — 형 앞에서 — 형의 입술에 — 자기 입술을 — 닿게 했다는 사실이.

그게 — 자기가 평생 한 번도 못 해본 일이었다는 사실이.

그게 — 지금 — 일어나고 있다는 사실이.

따라잡힌 순간, 그의 안쪽에서 — 무언가가 한꺼번에 풀려버렸다.

근떡존이 천천히 입술을 떼었다.

떼고 나서 — 시선을 형의 얼굴에서 떼지 못했다.

형의 표정이 평소와 살짝 달랐다. 평소의 형은 늘 한 발 앞에서 바라보는 사람이었다. 그런데 지금의 형은 — 살짝 멍한 얼굴로 떡존을 보고 있었다.

평소엔 잘 안 흔들리는 사람이 — 흔들렸다.

그게 보였다.

근떡존이 그것을 보고 — 자기 안쪽에서 또 한 번 무언가가 풀렸다.

"...형."

『...응.』

"제가 방금."

『...응.』

"...해버렸어요."

『...했네.』

"...진짜로요."

『...진짜로 했어.』

근떡존이 작게 웃었다.

웃음이 떨렸다. 그러나 멈출 수 없는 웃음이었다.

자기가 평생 못 할 줄 알았던 일을 — 방금 해버렸다는 것에 대한 — 거의 어이없는 종류의 웃음이었다.

"형."

『응.』

"한 번만 더 해도 돼요?"

『...떡존아.』

"안 되면 안 할게요."

『...해.』

근떡존이 또 한 번, 망설임 없이, 입술을 가져갔다.

이번엔 1초도 망설이지 않았다. 어차피 한 번 해본 일이었으니까. 그가 망설였던 이유는 — 평생 못 해본 일이라는 두려움 때문이었지, 좋아하는 마음이 부족해서가 아니었다.

좋아하는 마음만 따지면 — 그는 진작에 다섯 번도 더 했을 사람이었다.

두 번째 키스는 첫 번째보다 길었다.

세 번째 키스는 두 번째보다 더 길었다.

근떡존이 천천히 입술을 떼고, 형의 어깨에 이마를 묻었다. 평소처럼 부비기 시작했다. 그러나 오늘의 부비기는 평소와 결이 달랐다.

이건 부비는 게 아니라 — 그저 — 가까이 있고 싶은 거였다.

가까이 있다는 것을 — 한 번 더 — 한 번 더 — 한 번 더 — 확인하고 싶은 사람의 행동이었다.

"형."

『응.』

"저 평생 못 할 줄 알았어요."

『...키스?』

"네."

『그게 왜.』

"제가 그런 사람인 줄 알았어요."

"...평생 혼자일 줄 알았어요."

『...』

"근데 형 만난 다음에는 그 생각이 점점 사라졌고."

"오늘은 — 진짜로 — 사라진 것 같아요."

근떡존이 형의 어깨에 이마를 한 번 더 부볐다.

『떡존아.』

"네."

『떡존이는 평생 혼자 안 둘 거야.』

근떡존이 그 말을 듣고 — 또 한 번 작게 웃었다.

이번엔 떨림 없는 웃음이었다.

평생 혼자 안 둘 거라는 그 한 마디가 — 그가 평생 단 한 번도 받아본 적 없는 종류의 약속이었다.

그리고 오늘 처음 — 그 약속을 받았다.`,
