  min: { affinity: 9999 },
  imagePool: ["/pure_ch12_03.png"],
  background: "/bg_room_night.png",
  text: `첫 키스 이후 며칠이 지났다.

근떡존은 그 며칠 동안, 형 집에서 자고 가는 일이 더 잦아졌다. 평일에도 자고 갔다. 주말은 거의 다 형 집에 있었다. 형도 그것을 자연스럽게 받아주었다.

그런 어느 저녁, 떡존이 슬쩍 운을 떼었다.

"형."

『응.』

"저 형 집에 자주 오니까요."

『그렇지.』

"칫솔도 있고."

"옷도 있고."

"슬리퍼도 있고."

『있지.』

"...."

근떡존이 잠깐 시선을 떨궜다.

『말하고 싶은 거 있어?』

"...있어요."

『뭔데.』

"...."

근떡존이 시선을 살짝 들었다. 형의 얼굴을 봤다. 그리고 다시 떨궜다.

"...같이 살면 어때요?"

말하면서 시선이 자꾸 떨어졌다. 자기가 그 단어를 입에서 꺼냈다는 게 — 부끄러우면서도 — 너무 하고 싶었던 말이라 — 결국 흘러나오고 만 거였다.

형이 잠깐 그를 봤다.

평소엔 떡존의 어떤 제안에도 다정하게 반응하던 형이 — 이번엔 잠깐 — 멈췄다.

『...떡존아.』

"네."

『그건 좀.』

"...."

『형이 좀 더 생각해봐야 할 것 같아.』

근떡존이 한 번 굳었다.

평소엔 늘 받아주던 사람의 — 처음 보는 거절 직전의 톤이었다. 거절은 아니었다. 그러나 거절 쪽으로 한 발 기울어 있는 톤이었다.

근떡존이 그 톤을 즉각 알아챘다.

"...왜요."

『...형은 자기 공간이 좀 필요한 사람이라.』

"...."

『같이 사는 건 좀 다른 문제야.』

『잠깐 자고 가는 거랑 매일 함께 사는 건 다르거든.』

『형이 좀 시간 갖고 생각해볼게.』

근떡존이 잠깐 입을 다물었다.

평소의 그였다면 — 여기서 알겠다고 했을 것이다. 형이 시간을 갖고 싶다면 그 시간을 줄 수 있는 사람이 그였다. 형의 자기 공간을 존중할 수 있는 사람이 그였다.

그런데 오늘은 — 그게 안 됐다.

이미 말을 꺼낸 이상, 그의 안쪽에서는 — 그 말이 자기 의지를 가지고 자라기 시작했다.

같이 살고 싶었다. 그것도 그냥 살고 싶은 게 아니라 — 형 옆에서 매일 일어나고 싶었다. 형 옆에서 매일 자고 싶었다. 형이 옆에 없는 시간을 한 시간이라도 줄이고 싶었다.

이 마음이 — 한 번 입 밖으로 나온 이상 — 다시 안쪽으로 들어가지 않았다.

근떡존이 다시 입을 열었다.

"형."

『응.』

"진짜로 안 돼요?"

『...떡존아 형이 시간 갖고 생각한다고 했잖아.』

"근데 그 시간이 얼마나 걸려요."

『...』

"하루요? 일주일이요? 한 달이요?"

『...떡존아.』

"형 그냥 안 된다고 하시는 거 아니에요?"

근떡존의 톤이 살짝 변했다.

평소의 어리광이 아니었다. 평소엔 부탁의 톤이었던 게, 이제는 — 추궁에 가까운 톤이었다.

본인도 자기 톤이 변한 것을 느꼈다. 그러나 멈추지 못했다.

『떡존아.』

"네."

『형이 안 된다는 게 아니야.』

"근데 시간이 필요하다는 게 그거잖아요."

"형은 시간이 흐르면 결국 거절할 거예요."

『...떡존아 그건 너무 단정짓는 거야.』

"단정짓는 게 아니라."

근떡존이 자기도 모르게 목소리가 살짝 커졌다.

"형이 같이 살기 싫어한다는 거 알아요."

『...』

"형 표정 보면 알아요."

『...』

"...."

『...떡존아.』

"....."

근떡존이 갑자기 고개를 떨궜다.

자기가 방금 한 말이 — 평소의 자기 같지 않다는 것을 — 자기도 알았다.

그러나 인정하기 싫었다.

인정하면 사과해야 했고, 사과하면 이 얘기가 끝나는 거였고, 끝나면 — 형이 결국 거절하는 거였다.

그가 인정하지 않으면 — 이 얘기는 계속 이어진다.

이어지는 동안, 형이 마음을 바꿀 수도 있었다.

이건 — 평소의 다정한 어리광과는 결이 다른 — 처음으로 보이는 — 진짜 떼쓰기였다.

큰 덩치의 사람이 — 거절을 받아들이지 않으려고 — 진짜로 떼쓰는 모습이었다.

부끄러운 일이었다.

그러나 부끄러움보다 — 같이 살고 싶다는 마음이 — 더 컸다.`,
