  text: `11장의 그 거울 앞 미소 연습 이후, 떡존은 — 본인이 생각하기로 — 잘 해내고 있었다.

표면적으로는 평소의 떡존이었다. 어리광도 부렸고, 헤헤 거렸고, 형 앞에서 살짝 부끄러운 척도 했다. 매일 형을 만났다. 만나지 않는 날에는 한 시간에 한 번씩 메시지를 보냈다. 자기가 어디서 무엇을 하는지 형에게 다 알렸다.

본인은 그것이 — 사랑하는 사람을 향한 자연스러운 행동이라고 믿었다.

자기 노트에 적혀 있는 것들 — 「거짓말이 사랑이다」, 「★」 — 그런 것들은 본인의 무의식 어딘가에 있을 뿐, 평소의 자기는 그저 형을 사랑하는 평범한 사람이라고 — 본인은 진심으로 생각했다.

그게 가장 무서운 부분이었다.

그가 자기 자신을 — 그저 사랑이 깊은 사람이라고 — 진심으로 믿고 있다는 것.

그런데 — 그 믿음과 별개로 — 형의 안쪽에서는 작은 변화가 일어나고 있었다.

형은 사람을 잘 읽는 사람이었다. 그게 직업병이라고 했었다. 11장에 떡존이 폭주하면서 보여준 모습 — 매일 만나지 않으면 안 된다고 했던 그 톤 — 그것이 형 안쪽에서 작은 씨앗으로 자리 잡았다.

처음엔 그저 떡존이 좀 격해졌다고 생각했다. 사랑하는 사람이 격해지는 일은 — 어떤 종류의 사랑이든 — 가능한 일이었다.

그런데 며칠이 지날수록 — 작은 씨앗이 — 점점 자라났다.

오늘 아침에도 메시지가 왔다.

"형 일어났어요?"
"형 오늘 학교에서 누구랑 점심 먹어요?"
"형 점심 먹고 카톡 보내주세요"
"형 답장 빨리 좀"
"형 형 답장이요"
"...."

5분 사이에 다섯 줄이었다.

『떡존아 형 지금 학교야 답장 천천히 할게』

답장을 보내고, 형은 잠깐 휴대폰을 내려놓았다.

평소엔 그저 자연스럽게 답장하던 일이 — 오늘은 — 한 번 멈춰서 답장하게 됐다.

이상한 일이었다.

이 사람이 자기에게 보내는 메시지가 — 점점 — 평범한 카톡이 아니라 — 보고서 같은 결을 가지기 시작했다는 것.

매번 자기 동선을 보고하고, 매번 자기 일정을 알리고, 매번 자기가 누구와 무엇을 하는지 적어 보내는 것.

처음엔 그저 다정하게 보였던 그 행동들이 — 오늘은 — 살짝 무겁게 느껴졌다.

『...』

형이 휴대폰을 다시 들었다.

『떡존아 답장 천천히 해도 돼』

'네 형'
'근데 답장이 너무 늦으면 좀 그래서요'
'그래서요?'
'아니에요'
'형 학교 일 잘 하세요'

마지막 메시지가 한 줄. 그 한 줄도 평소엔 자연스럽게 보였을 텐데, 오늘은 — 그 안에 어떤 보복 같은 게 묻어 있는 것처럼 느껴졌다.

답장이 늦으면 안 되는 사람.

그게 떡존이 보여주고 있는 모양새였다.

형이 그 메시지를 한참 보고 있었다.

이건 작은 일이었다. 단지 메시지 빈도가 좀 잦은 것뿐이었다. 단지 답장이 늦으면 떡존이 살짝 토라지는 것뿐이었다. 단지 떡존이 자기 동선을 다 알리는 것뿐이었다.

그런데 그 작은 것들이 — 며칠 사이 — 점점 더 분명한 패턴으로 자리 잡고 있었다.

이게 사랑인가. 아니면 다른 무엇인가.

형이 그 질문을 자기 안쪽에서 — 처음으로 — 진지하게 던져봤다.

답이 잘 나오지 않았다.`,
