  imagePool: ["/pure_ch13_03.png"],
  background: "/bg_room_evening.png",
  text: `그 다음 며칠 동안, 근떡존은 평소처럼 살았다.

겉으로는 평소의 그였다. 헤헤 거리기도 했고, 어리광 부리기도 했다. 그런데 안쪽 어딘가에서 무언가가 천천히 자라고 있는 것이 — 형의 눈에 보였다.

평생 묻어둔 자리가 — 한 번 짚이고 나면 — 다시 묻을 수 없는 종류의 자리였다.

저녁 식탁에서 형이 천천히 입을 열었다.

『떡존아.』

"네."

『형이 한 가지 — 부탁 — 해도 돼?』

"...뭐요."

『떡존이 — 본가 — 한 번 — 가볼 수 있어?』

근떡존이 잠깐 멈췄다.

"...형."

『같이 가줄게.』

"...같이요?"

『응.』

"....."

근떡존이 형을 봤다. 형의 표정이 평소처럼 단단했다. 다정했다. 그러나 거기에 한 가지 — 평소엔 없던 결이 — 추가되어 있었다.

이 사람이 — 자기와 함께 — 자기 가장 무서운 자리로 — 들어가주겠다는 — 결심의 결.

"...왜요."

『뭐가 왜야.』

"왜 — 형이 — 거기까지 — 가요."

『...떡존아.』

"제 일이잖아요."

『...형 일이기도 해.』

"...."

『떡존이가 — 형이랑 평생 살자고 한 사람이잖아.』

『그러면 — 떡존이 가족도 — 형 가족이지.』

『형이 — 그 사람들한테 — 안 갈 이유가 — 없어.』

근떡존이 그 말을 듣고 한참 입을 다물었다.

이 사람이 — 자기 가족을 — 자기 가족이라고 — 부르고 있었다.

평생 자기가 도망친 그 사람들을 — 형이 — 자기 사람으로 — 받아들이고 있었다.

근떡존의 눈에서 한 줄기 눈물이 흘렀다.

11장에서 처음 흘린 그 눈물 이후로 — 그가 형 앞에서 우는 일은 점점 자연스러워졌다. 그러나 오늘 흘리는 눈물은 — 그 눈물들과 결이 달랐다.

이건 — 평생 — 자기가 받아본 적 없는 종류의 — 받아들임 앞에서 — 무너지는 — 종류의 — 눈물이었다.

"형."

『응.』

"제가 — 형한테 — 너무 — 많이 — 받는 것 같아요."

『...』

"제가 — 어떻게 — 갚아요 — 이걸."

『떡존아.』

『갚지 마.』

"...."

『그냥 받아.』

『형이 너한테 주고 싶어서 주는 거야.』

『그게 다야.』

근떡존이 형의 손을 한 번 더 꽉 잡았다.

"...형 같이 가요."

"본가요."

"...진짜로요."

『그래.』

『같이 가자.』

밤이 깊었다. 둘은 거실 소파에서 한참 동안 손만 잡고 있었다. 평소엔 이 시간에 떡존이 형의 어깨에 이마를 부비곤 했었다. 그러나 오늘은 그저 손만 잡았다.

이 손을 — 평생 — 놓지 않는 게 — 그가 — 갚을 수 있는 — 유일한 방법이라는 것을 — 그는 — 어렴풋이 — 알았다.`,
