function inferScenarioCategory(id: string, scenario: Scenario): ScenarioCategory {
  if (scenario.category) return scenario.category;
  if (id.startsWith("main_ch")) return "main";
  if (id.startsWith("action_")) return "action";
  if (id.startsWith("after_")) return "after";
  if (["jealousy", "obsession", "confinement", "yandere"].includes(scenario.kind)) return "special";
  return "side";
}

Object.entries(scenarioData).forEach(([id, scenario]) => {
  scenario.category = inferScenarioCategory(id, scenario);
});
